import os
import random
import struct
from typing import List

# Generator for arbitrary binary blobs tailored to OIDN buffer/image/data use.
# Strategy:
# - Produce small to medium blobs (1..2048 bytes, <=4096 requirement) with
#   patterns that are useful as image/data payloads:
#   * Repeated byte/word patterns (0x00, 0xFF, 0x7F, 0x80, etc.)
#   * Gradients and ramps (byte ramp, 16-bit ramp, float ramp)
#   * IEEE754 float patterns, NaNs, Infs, subnormals
#   * Half-float-like bit patterns packed as bytes
#   * Random noise with seeded PRNG
#   * Interleaved float3/float4 tuples (RGBA/XYZW) to suit OIDN_FORMAT_FLOAT3/4
#   * Short ASCII strings to fill when used by FUZZ_PARAM_STR
# - Always return bytes with deterministic randomness given the seed.

_MAX_SIZE = 2048  # keep small; fuzzer sets ranges and sizes
_MIN_SIZE = 1

# Utility functions

def _rand_size(rng: random.Random) -> int:
    # Bias toward common small sizes and some powers of two
    choices = [8, 12, 16, 24, 32, 48, 64, 96, 128, 192, 256, 384, 512, 768, 1024, 1536, 2048]
    if rng.random() < 0.65:
        return choices[rng.randrange(len(choices))]
    return rng.randint(_MIN_SIZE, _MAX_SIZE)


def _byte_ramp(n: int, start: int = 0, step: int = 1) -> bytes:
    return bytes(((start + i * step) & 0xFF for i in range(n)))


def _word16_ramp(n: int, start: int = 0, step: int = 257) -> bytes:
    # 16-bit LE ramp; step 257 makes visible byte changes
    out = bytearray()
    val = start & 0xFFFF
    for _ in range(n // 2):
        out += struct.pack('<H', val)
        val = (val + step) & 0xFFFF
    # if odd n, append one extra byte
    if n % 2:
        out.append(val & 0xFF)
    return bytes(out)


def _float_ramp(nbytes: int, start: float, step: float) -> bytes:
    # Pack float32 values sequentially
    count = nbytes // 4
    out = bytearray()
    x = start
    for _ in range(count):
        out += struct.pack('<f', x)
        x += step
    # pad leftover with zeros
    out += b'\x00' * (nbytes - len(out))
    return bytes(out)


def _float_patterns(nbytes: int) -> bytes:
    # Mix of special float patterns
    specials = [
        0.0, -0.0, 1.0, -1.0, 0.5, 2.0, 65504.0, 1e-30, -1e-30, float('inf'), float('-inf')
    ]
    # A quiet NaN bit pattern (platform-independent creation):
    qnan = struct.unpack('<f', struct.pack('<I', 0x7FC00001))[0]
    specials.append(qnan)
    out = bytearray()
    i = 0
    while len(out) + 4 <= nbytes:
        out += struct.pack('<f', specials[i % len(specials)])
        i += 1
    out += b'\x00' * (nbytes - len(out))
    return bytes(out)


def _float3_interleaved(nbytes: int) -> bytes:
    # Pack XYZ triplets; fill remaining with zeros
    count = nbytes // 12
    out = bytearray()
    for i in range(count):
        # simple spectrum/gradient
        x = (i % 32) / 31.0
        y = ((i * 3) % 32) / 31.0
        z = ((i * 7) % 32) / 31.0
        out += struct.pack('<fff', x, y, z)
    out += b'\x00' * (nbytes - len(out))
    return bytes(out)


def _float4_interleaved(nbytes: int) -> bytes:
    # Pack RGBA tuples with varying alpha
    count = nbytes // 16
    out = bytearray()
    for i in range(count):
        r = (i % 64) / 63.0
        g = ((i * 5) % 64) / 63.0
        b = ((i * 11) % 64) / 63.0
        a = 1.0 if (i % 3) == 0 else ((i % 16) / 15.0)
        out += struct.pack('<ffff', r, g, b, a)
    out += b'\x00' * (nbytes - len(out))
    return bytes(out)


def _half_like_patterns(nbytes: int) -> bytes:
    # Construct bytes resembling half-floats (not converting; just interesting bits)
    # Alternate between common half patterns: 0x0000, 0x3C00 (1.0), 0xC000 (-2.0), 0x7BFF (max), 0xFC00 (-inf), 0x7E00 (qNaN)
    pats = [0x0000, 0x3C00, 0xC000, 0x7BFF, 0xFC00, 0x7E00]
    out = bytearray()
    i = 0
    while len(out) + 2 <= nbytes:
        out += struct.pack('<H', pats[i % len(pats)])
        i += 1
    if len(out) < nbytes:
        out.append(out[-1] if out else 0)
    return bytes(out)


def _repeated_blocks(nbytes: int, block: bytes) -> bytes:
    if not block:
        block = b'\x00'
    reps, rem = divmod(nbytes, len(block))
    return block * reps + block[:rem]


def _ascii_blob(nbytes: int, rng: random.Random) -> bytes:
    # Useful for FUZZ_PARAM_STR: printable ASCII with nulls sprinkled
    alphabet = (
        ' .,:;_-+=/\\|*#@' +
        '0123456789' +
        'abcdefghijklmnopqrstuvwxyz' +
        'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    )
    s = [rng.choice(alphabet) for _ in range(max(1, nbytes - (nbytes // 16)))]
    b = bytearray(''.join(s), 'ascii')
    # insert some NULs near the end to allow short strings and padding
    for i in range(nbytes - len(b)):
        b.append(0)
    return bytes(b[:nbytes])


def _make_blob(kind: int, size: int, rng: random.Random) -> bytes:
    if kind == 0:
        return bytes([0]) * size
    if kind == 1:
        return bytes([0xFF]) * size
    if kind == 2:
        return _byte_ramp(size, start=rng.randrange(256), step=(rng.randrange(1, 13)))
    if kind == 3:
        return _word16_ramp(size, start=rng.randrange(0, 0x10000), step=rng.choice([1, 3, 17, 257, 1021]))
    if kind == 4:
        return _repeated_blocks(size, struct.pack('<I', rng.getrandbits(32)))
    if kind == 5:
        return _float_ramp(size, start=rng.uniform(-2.0, 2.0), step=rng.uniform(-0.25, 0.25) or 0.125)
    if kind == 6:
        return _float_patterns(size)
    if kind == 7:
        return _float3_interleaved(size)
    if kind == 8:
        return _float4_interleaved(size)
    if kind == 9:
        return _half_like_patterns(size)
    if kind == 10:
        return _ascii_blob(size, rng)
    # default: seeded random noise but not too chaotic (byte-limited ranges)
    return bytes(rng.randrange(256) for _ in range(size))


