    rng = random.Random(seed)

    size = _rand_size(rng)

    # Choose one or more segments and concatenate to form diverse payloads,
    # keeping total <= size.
    segments: List[bytes] = []
    remaining = size

    # Decide number of segments (1..4)
    nseg = 1 + int(rng.random() * 4)

    for _ in range(nseg):
        if remaining <= 0:
            break
        seg_size = rng.randint(max(1, remaining // (nseg - len(segments)) if (nseg - len(segments)) > 0 else 1), remaining)
        kind = rng.randrange(12)
        segments.append(_make_blob(kind, seg_size, rng))
        remaining -= seg_size

    blob = b''.join(segments)

    # To increase chance of valid image interpretation when used by SetSharedFilterImage,
    # ensure alignment-friendly length for float3/4 formats occasionally.
    if rng.random() < 0.3:
        # pad to multiple of 12 or 16 randomly
        align = rng.choice([12, 16, 4, 2])
        pad = (-len(blob)) % align
        if pad:
            blob += _make_blob(rng.randrange(12), pad, rng)

    # Cap to 2048 bytes (already ensured by size selection), and enforce >=1 byte
    blob = blob[:_MAX_SIZE]
    if not blob:
        blob = b"\x00"

    return blob
